                border-color: aqua !important;
            }

            .flex.gap-2.flex-wrap.pt-4 .UI-Badge__root:nth-child(2),
            .group\\/extension-card .UI-Badge__root:nth-child(2) {
                color: #4ade80 !important;
                border-color: #4ade80 !important;
            }

            .flex.gap-2.flex-wrap.pt-4 .UI-Badge__root:nth-child(3),
            .group\\/extension-card .UI-Badge__root:nth-child(3) {
                color: #f87171 !important;
                border-color: #f87171 !important;
                padding-left: 8px !important;
                padding-right: 8px !important;
